const authorization = controls === legacy.REVIEW_CONTROL_REASON ? await legacy.purposeConfirmation(github, repo, pr, comments) : null;
// A verified receipt still never grants owner confirmation. Name which rule holds the review.
const held = (cause, message) => Object.assign(new Error(message), {code: 'RECEIPT_AUTHORITY', cause_code: cause});
if (controls && !authorization) {
  throw held('receipt_protected_controls', 'A verified local receipt cannot authorize a change to protected review controls ' +
    '(AGENTS.md, CI workflow or configuration, the repository policy or another configured sensitive path); ' +
    'the exact-head owner confirmation is missing.');
}
// The gate publishes this receipt's findings on its first run, before an owner confirmation or a base update lets a
// later run finish. A ledger whose findings equal exactly what this signed record reconciles to is that publication,
// not a change; any other history still voids the receipt. The record keeps the signed history either way, so the gate
// re-derives exactly the ledger it already published.
const own = digest(previous.findings) === digest(reconcile({...verified.record.result, reviews: verified.reviews},
  verified.record.snapshot, verified.record.previous.findings).findings);
const recorded = own ? {...previous, findings: verified.record.previous.findings} : previous;
if (digest(previous.findings) !== digest(verified.record.previous.findings) && !own) {
  throw held('receipt_history_changed', 'The review findings recorded on the pull request changed after the local receipt was issued.');
}
// A maintainer-attested receipt (an enrolled maintainer reviewed another author's pull request) is named as such.
const attested = verified.attestation;
const kind = attested ? 'Maintainer-attested' : 'Authenticated';
const signedBy = attested ? ` Signed by \`${attested.signer}\` for the pull request by \`${attested.author}\`.` : '';
if (technicalBlock) {
  if (report) report(`${kind} local Clouseau quality review verified.${signedBy} Independent CI acceptance remains blocked. CI AI calls: 0.`);
  return {...identity, ...technicalBlock, review_source: attested ? 'maintainer_attested' : 'authenticated_local', provider_api_calls: 0,
    reason: `${kind} local quality review verified without an AI rerun; independent CI acceptance remains blocked: ${technicalBlock.reason}`};
}
const record = localRecord(verified.record, {engine, authorization, previous: recorded, technical, author: pr.user.login,
  artifact: receiptRef, bundle, discovery});
// The signed bundle already lives at an immutable reference. Transport
// only the run-specific facts; the write boundary rehydrates and
// independently re-verifies the complete record from that reference.
const compact = {version: 2, local_receipt_reference: true, local_artifact: receiptRef,
  local_author: pr.user.login, previous: recorded, technical, discovery, ...(engine ? {engine} : {}),
  ...(authorization ? {local_authorization: authorization} : {})};
fs.writeFileSync(recordPath, JSON.stringify(compact, null, 2) + '\n');
if (report) report(`${kind} local Clouseau review verified.${signedBy} CI AI calls: 0.`);
return {...identity, decision: authorization ? 'owner_decision' : 'auto_approve', record_digest: digest(record),
  record_reference_digest: digest(compact), review_source: attested ? 'maintainer_attested' : 'authenticated_local', provider_api_calls: 0,
  reason: `${kind} passing local review; source, scores and CI verification validated without an AI rerun.`};

// The heads a force push of this pull request replaced or produced, read by the engine from the pull request's own timeline
// (never from comment text). More force pushes than one page holds is evidence the engine did not read: none is returned.
const FORCE_PUSHES = 'query($owner:String!,$repo:String!,$number:Int!){repository(owner:$owner,name:$repo){pullRequest(number:$number){' +
  'timelineItems(itemTypes:[HEAD_REF_FORCE_PUSHED_EVENT],first:100){totalCount nodes{...on HeadRefForcePushedEvent{beforeCommit{oid} afterCommit{oid}}}}}}}';
async function forcePushedHeads(github, repo, number) {
  const items = (await github.graphql(FORCE_PUSHES, {owner: repo.owner, repo: repo.repo, number})).repository?.pullRequest?.timelineItems;
  if (!items || items.totalCount > items.nodes.length) return null;
  return [...new Set(items.nodes.flatMap(node => [node?.beforeCommit?.oid, node?.afterCommit?.oid]).filter(oid => /^[a-f0-9]{40}$/.test(String(oid))))];
}

// Whether a confirmation of commit `sha` (an `/approve-intent` comment or an approving review) covers the pull request's head.
// It always does for the exact head. Only with the protected `local_review.confirmation: "diff"` (`intentDiff`) does it also cover a
// later head of the same pull request whose normalized diff (receipt-patch.cjs) equals the diff `sha` had from its merge base
// with the live base: a branch update that leaves the change unchanged keeps the owner's confirmation, any other push voids
// it. `sha` must have been a head of this pull request: an ancestor of its head, or (after a rebase) of a head that one of its
// force pushes replaced or made. A patchless or truncated file list, or an unknown commit, never matches. The
// base `sha` was confirmed against must carry the same protected configuration and purpose contract as the live base: a
// confirmation never carries across a base change to either.
const confirmations = new Map();
async function confirms(github, repo, pr, sha) {
  if (sha === pr.head.sha) return true;
  if (!intentDiff || typeof sha !== 'string' || !/^[a-f0-9]{40}$/.test(sha)) return false;
  const key = `${repo.owner}/${repo.repo}#${pr.number}:${pr.base.sha}:${pr.head.sha}:${sha}`;
  // A failed comparison is not kept: the next call (a rate-limit retry) compares again.
  if (!confirmations.has(key)) confirmations.set(key, (async () => {
    const {canonicalHunks, diffDigest, splitDeclarations} = require('./receipt-patch.cjs');
    // Compatibility declarations compare by their meaning (verdict and covered files), exactly as the receipt binding compares
    // them (receipt-patch.cjs splitDeclarations): a re-declaration after a base merge that keeps every verdict carries the
    // confirmation as it carries the receipt; a changed verdict or a newly declared file does not. Every other file compares
    // byte for byte, as before.
    const normalized = files => {
      if (files.length === 0 || files.length >= 300 || files.some(file => typeof file.patch !== 'string' || !file.patch)) return null;
